export type FontRole = 'display' | 'body' | 'numeric';

export type FontWeight = 400 | 500 | 600 | 700 | 800;

export type NativeFontName =
  | 'Archivo-Regular'
  | 'Archivo-Medium'
  | 'Archivo-SemiBold'
  | 'ArchivoCondensed-Bold'
  | 'ArchivoCondensed-ExtraBold';

/** Static instance files, relative to the `@kadro/brand` package root (for `expo-font`). */
export const nativeFontFiles: Readonly<Record<NativeFontName, string>> = {
  'Archivo-Regular': 'fonts/archivo/static/Archivo-Regular.ttf',
  'Archivo-Medium': 'fonts/archivo/static/Archivo-Medium.ttf',
  'Archivo-SemiBold': 'fonts/archivo/static/Archivo-SemiBold.ttf',
  'ArchivoCondensed-Bold': 'fonts/archivo/static/ArchivoCondensed-Bold.ttf',
  'ArchivoCondensed-ExtraBold': 'fonts/archivo/static/ArchivoCondensed-ExtraBold.ttf',
};

export type TypeVariant =
  | 'caption'
  | 'footnote'
  | 'label'
  | 'body'
  | 'bodyStrong'
  | 'title3'
  | 'title2'
  | 'title1'
  | 'display'
  | 'numeral'
  | 'score'
  | 'bib'
  | 'numeralXL';

export interface TextStyleToken {
  readonly role: FontRole;
  /** Static instance name; it already carries the weight and the width. */
  readonly fontFamily: NativeFontName;
  readonly fontSize: number;
  readonly lineHeight: number;
  readonly fontWeight: FontWeight;
  /** Points (the token's em value times the size). */
  readonly letterSpacing: number;
  /** `fontVariant: ['tabular-nums']` for counts, times, fees and kit numbers. */
  readonly tabularNums: boolean;
}

